/* ==========================================================================
   第 4 級的一般字

   第 3 級是「多半連看都不一定看得懂」，這一級再往外一圈：字的**使用場合更窄**，
   多半綁在某個領域上 —— 醫療（abdomen、arthritis、biopsy）、法律（barrister、
   affidavit）、軍事（arsenal、artillery）、學科名（anthropology、archaeology）。
   多益不會整篇考這些字，但一篇文章裡卡住一個就夠讓人讀不下去。

   前三級那四條做法照舊，這一級各自更明顯：

   一是**英美成對的字達到高峰**：armor／armour、artefact／artifact、appal／appall、
   authorise／authorize、aging／ageing、behavioural／behavioral。兩邊都收（ECDICT
   本來就分別收了），但不當成兩個字 —— `note` 裡說明是哪一邊並指過去。

   二是**成對的易混字**：ascent／assent、altar／alter、affective／effective、
   bloc／block、biannual／biennial。

   三是 `en` 走偏的比例比第 3 級更高，而且偏的方式更離譜：`attic` 的英英是古希臘
   方言、`angler` 是「陰謀家」、`barber` 是一位美國作曲家、`bailey` 是一位美國歌手。
   碰到就自己寫一句蓋掉。

   四是**人名地名縮寫**在這一級大量出現（aberdeen、blake、blackpool、bobby、
   basil）。照樣要寫，但 `note` 裡講明「這是人名／地名，寫的時候要大寫」。

   一樣照字母排，一樣每筆兩句中英對照例句。
   ========================================================================== */

/* ===================== A ===================== */
